from pathlib import Path
from zoneinfo import ZoneInfo

import pandas as pd


DATASET = Path("/app/dataset")
REPORT_START = datetime(2024, 3, 15, tzinfo=timezone.utc)
REPORT_END = datetime(2024, 3, 16, tzinfo=timezone.utc)
BTU_TO_KWH = 0.0002930710701722222


def _normalized_name(value: object) -> str:
    return " ".join(str(value).strip().lower().split())


def _encoding_for(path: Path) -> str:
    with path.open("rb") as f:
        marker = f.read(2)
    return "utf-16" if marker in (b"\xff\xfe", b"\xfe\xff") else "utf-8-sig"


def _separator_for(path: Path, encoding: str) -> str:
    with path.open(encoding=encoding, errors="replace") as f:
        for _ in range(3):
            next(f)
        header = next(f)
    return ";" if header.count(";") > header.count(",") else ","


def _parse_number(value: object) -> float:
    if pd.isna(value):
        return float("nan")
    if not isinstance(value, str):
        return float(value)

    text = value.strip()
    if not text or text.upper() == "ERR":
        return float("nan")
    if "," in text:
        text = text.replace(".", "").replace(",", ".")

    try:
        return float(text)
    except ValueError:
        return float("nan")


def _parse_local_datetime(value: object):
    if pd.isna(value):
        return pd.NaT

    text = str(value).strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%d.%m.%Y %H:%M:%S"):
        try:
            return datetime.strptime(text, fmt)
        except ValueError:
            pass
    return pd.NaT


def _load_production(farm_id: str) -> pd.DataFrame:
    path = DATASET / f"production_{farm_id}.csv"
    encoding = _encoding_for(path)
    return pd.read_csv(
        path,
        encoding=encoding,
        skiprows=3,
        sep=_separator_for(path, encoding),
        dtype=str,
        engine="python",
    )


def _farm_metadata() -> pd.DataFrame:
    farms = pd.read_csv(DATASET / "farms.csv")
    registry = pd.read_csv(DATASET / "farm_registry.csv")

    farms["name_key"] = farms["farm_name"].map(_normalized_name)
    registry["name_key"] = registry["farm_name"].map(_normalized_name)
    return registry.merge(
        farms[["name_key", "timezone"]],
        on="name_key",
        how="left",
    )


def _calibration_config() -> dict:
    with (DATASET / "sensors_calibration.json").open() as f:
        data = json.load(f)
    return data["enterprise_platform"]["deployment_environments"]["system_config"][
        "farms"
    ]


def _completed_maintenance_windows() -> dict[str, list[tuple[datetime, datetime]]]:
    return {
        "FARM_C": [(datetime(2024, 3, 16, 8), datetime(2024, 3, 16, 12))],
        "FARM_F": [(datetime(2024, 3, 15, 12), datetime(2024, 3, 15, 14))],
    }


def _nominal_interval_hours(local_datetimes: pd.Series) -> float:
    values = sorted(value for value in local_datetimes if pd.notna(value))
    if len(values) < 2:
        return 0.0

    diffs = [
        (right - left).total_seconds()
        for left, right in zip(values, values[1:])
        if (right - left).total_seconds() > 0
    ]
    if not diffs:
        return 0.0
    return max(set(diffs), key=diffs.count) / 3600.0


def answer() -> dict[str, int]:
    metadata = _farm_metadata()
    calibration = _calibration_config()
    maintenance_windows = _completed_maintenance_windows()
    unit_multiplier = {
        "kwh": 1.0,
        "mwh": 1000.0,
        "wh": 0.001,
        "btu": BTU_TO_KWH,
    }

    totals: dict[str, int] = {}

    for _, farm in metadata.iterrows():
        farm_id = farm["farm_id"]
        config = calibration.get(farm_id)
        if config is None:
            totals[farm_id] = 0
            continue

        df = _load_production(farm_id)
        timestamp_column = next(col for col in df.columns if col.strip() == "timestamp")
        df["_local_dt"] = df[timestamp_column].map(_parse_local_datetime)
        df = df.drop_duplicates(subset=["_local_dt"], keep="last")
        df = df[df["_local_dt"].notna()].copy()

        if df.empty:
            totals[farm_id] = 0
            continue

        nominal_interval_hours = _nominal_interval_hours(df["_local_dt"])
        df["_temp_c"] = df["inverter_temperature_C"].map(_parse_number)

        if (df["_temp_c"] > 85.0).any():
            invalid = pd.Series(False, index=df.index)
            for spike_time in df.loc[df["_temp_c"] > 85.0, "_local_dt"]:
                invalid |= (df["_local_dt"] > spike_time) & (
                    df["_local_dt"] <= spike_time + timedelta(minutes=45)
                )
            df = df[~invalid].copy()

        for window_start, window_end in maintenance_windows.get(farm_id, []):
            df = df[
                ~(
                    (df["_local_dt"] >= window_start)
                    & (df["_local_dt"] < window_end)
                )
            ].copy()

        farm_zone = ZoneInfo(farm["timezone"])
        df["_utc_dt"] = df["_local_dt"].map(
            lambda value: value.replace(tzinfo=farm_zone).astimezone(timezone.utc)
        )
        df = df[(df["_utc_dt"] >= REPORT_START) & (df["_utc_dt"] < REPORT_END)].copy()

        value_column = config["calibration_data"]["value_column_name"]
        offset = float(config["calibration_data"]["calibration_offset"])
        df["_true_value"] = df[value_column].map(_parse_number) - offset
        df = df[df["_true_value"].notna() & (df["_true_value"] >= 0)].copy()

        sensor_info = config["sensor_info"]
        if sensor_info["reading_type"].lower() == "energy":
            total_kwh = df["_true_value"].sum() * unit_multiplier[
                sensor_info["unit"].lower()
            ]
        else:
            total_kwh = df["_true_value"].sum() * nominal_interval_hours

        totals[farm_id] = int(round(total_kwh))

    return totals


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
